require_once __DIR__ . '/../../includes/admin_auth.php';require_admin();$id=valid_id($_GET['id']??$_POST['id']??null);if($id===null)redirect('index.php');$get=$pdo->prepare('SELECT id,title,image FROM courses WHERE id=:id LIMIT 1');$get->execute(['id'=>$id]);$course=$get->fetch();if(!$course)redirect('index.php');if(is_post_request()){if(!verify_csrf_token($_POST['csrf_token']??null))exit('Invalid request.');$delete=$pdo->prepare('DELETE FROM courses WHERE id=:id');try{$delete->execute(['id'=>$id]);}catch(PDOException $exception){error_log('Course deletion failed: '.$exception->getMessage());exit('This course cannot be deleted while it has related records.');}delete_uploaded_image($course['image'],'courses');redirect('index.php');}admin_header('Delete Course','courses/index.php');
?><div class="card table-card"><div class="card-body p-4"><h2 class="h5">Delete “<?=e($course['title'])?>”?</h2><p class="text-secondary">Related fees, syllabus modules and enrollments may prevent deletion.</p><form method="post"><input type="hidden" name="id" value="<?=e($id)?>"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button class="btn btn-danger" type="submit">Confirm Delete</button><a class="btn btn-outline-secondary ms-2" href="index.php">Cancel</a></form></div></div><?php admin_footer();?>
